    private static SalesDocumentationExample E(
        string section,
        string title,
        string[] transactionCodes,
        string[] operationCodes,
        string explanation,
        string pages) =>
        new(section, title, transactionCodes, operationCodes, explanation,
            $"Руководство интегратора Frontol 6, раздел 17.2.2, {pages}");
