public sealed record SalesDocumentationExample(
    string Section,
    string Title,
    IReadOnlyList<string> TransactionCodes,
    IReadOnlyList<string> OperationCodes,
    string Explanation,
    string ManualReference)
{
    public string TransactionText => TransactionCodes.Count == 0
        ? "шапка / общие правила"
        : string.Join(", ", TransactionCodes.Select(code => $"№{code}"));
    public string OperationText => OperationCodes.Count == 0
        ? "—"
        : string.Join(", ", OperationCodes.Select(code => $"{code} — {OperationName(code)}"));

    private static string OperationName(string code) =>
        FrontolSalesTransactionCatalog.OperationTypes.TryGetValue(code, out var name) ? name : $"операция {code}";
}

public sealed record SalesDocumentationExampleSummary(
    string Section,
    string Title,
    string TransactionText,
    string OperationText,
    string Explanation,
    string ManualReference,
    int MatchingTransactionCount)
{
    public string PresenceText => MatchingTransactionCount > 0
        ? $"Есть в файле: {MatchingTransactionCount:N0}"
        : "Нет в текущем файле — пример доступен в справке";
}
